/**
 * Regeneration block for the LEFT panel.
 *
 * When the user asks the AI to replan an activity or a section, we show a NEW
 * block below their instruction that looks EXACTLY like the initial-planning
 * checklist (spinner→check item head + clamped Markdown detail with "Show
 * more"/"Show less"), streaming in real time — with two differences:
 *  - replan_activity: each item's head is the ACTIVITY title (not the section
 *    name) prefixed by the activity's monologo icon (same as the center view,
 *    smaller). Two activities → two separate items.
 *  - replan_section: each item is a section, identical to initial planning.
 *
 * The block is built additively into the post-review feed (#cgLogAfter). The
 * top "structure I planned" checklist is left untouched. The live build (driven
 * by stream events) and the reload rebuild (from the persisted plan) call the
 * SAME item renderer, so reload === live.
 *
 * This module owns the live streaming state and its item builders
 * (``buildItem``/``createBlock``, exported for reuse). Rebuilding a block from
 * an authoritative, persisted plan - on reload, and for the approved-plan
 * summary - lives in regen-block-reload.js, which imports those builders
 * rather than duplicating them.
 *
 * @module     local_coursegen/local/courseai/ui/regen-block
 * @copyright  2026 Wilber Narvaez <https://datacurso.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import {renderMarkdown} from 'local_coursegen/local/courseai/ui/markdown';
import {formatActivityDetailMd, formatSectionMd} from 'local_coursegen/local/courseai/ui/plan_markdown';
import {clampDetail} from 'local_coursegen/local/courseai/ui/plan-transcript';
import {getActivityIconUrl, escapeHtml} from 'local_coursegen/local/courseai/utils';

/** @type {HTMLElement|null} The list of the regen block currently streaming. */
let activeList = null;
/** @type {Map<string, HTMLElement>} target id (activity or section) -> its <li>. */
let activeItems = new Map();
/** @type {Map<string, string>} activity id -> its description (from the plan). */
let activeDesc = new Map();
/**
 * Live section streaming: section id -> { item, description, activities }.
 * Used while ADDING or REGENERATING a section, where the section's structure and
 * its activities stream in event-by-event (no pre-known ids), so each section's
 * detail is re-rendered as activities and their detailed plans arrive.
 *
 * @type {Map<string, {item: HTMLElement, description: string, activities: Map<string, Object>}>}
 */
let sectionEntries = new Map();

/**
 * The spinner/check circle markup shared with the initial-planning checklist.
 *
 * @returns {string}
 */
const checkMarkup = () => '<span class="courseai-checklist-check">'
    + '<svg class="spinner-icon" viewBox="0 0 24 24">'
    + '<path d="M12 2a10 10 0 0 1 10 10" stroke-linecap="round"/></svg>'
    + '<svg class="check-icon" viewBox="0 0 24 24">'
    + '<polyline points="20 6 9 17 4 12"/></svg></span>';

/**
 * Build one checklist item element (head + empty/filled detail).
 *
 * @param {Object} opts
 * @param {string} opts.id - Target id (activity or section UUID).
 * @param {string} opts.title - Head label (activity or section title).
 * @param {string} [opts.iconType] - Activity type for the monologo icon (activity items only).
 * @param {string} [opts.detailHtml] - Pre-rendered detail HTML (reload), else empty (live).
 * @param {boolean} [opts.done] - Render in the done (check) state.
 * @returns {HTMLElement}
 */
export const buildItem = ({id, title, iconType, detailHtml = '', done = false}) => {
    const item = document.createElement('li');
    let itemState = 'is-loading';
    if (done) {
        itemState = 'is-done';
    }
    item.className = 'courseai-checklist-item ' + itemState;
    item.setAttribute('data-regen-id', String(id || ''));
    let icon = '';
    if (iconType) {
        const iconUrl = getActivityIconUrl(iconType);
        const escapedIconUrl = escapeHtml(iconUrl);
        icon = '<img class="cg-activity-icon" src="' + escapedIconUrl
            + '" alt="" onerror="this.style.display=\'none\'">';
    }
    const safeTitle = String(title || '');
    item.innerHTML = '<div class="courseai-checklist-head">'
        + checkMarkup()
        + icon
        + '<span class="courseai-checklist-name">' + escapeHtml(safeTitle) + '</span>'
        + '</div>'
        + '<div class="courseai-checklist-detail cg-log-md">' + detailHtml + '</div>';
    return item;
};

/**
 * Create the regen block container and append it to the post-review feed.
 *
 * @returns {HTMLElement|null} The <ul> list, or null when the feed is missing.
 */
export const createBlock = () => {
    const feed = document.getElementById('cgLogAfter') || document.getElementById('cgLog');
    if (!feed) {
        return null;
    }
    const container = document.createElement('div');
    container.className = 'courseai-checklist cg-regen-block';
    const list = document.createElement('ul');
    list.className = 'courseai-checklist-list';
    container.appendChild(list);
    feed.appendChild(container);
    return list;
};

/**
 * Find one activity by id within a single section.
 *
 * @param {Object} section
 * @param {string} activityId
 * @returns {Object|null}
 */
const findActivityInSection = (section, activityId) => {
    for (const activity of (section.activities || [])) {
        if (activity && activity.id === activityId) {
            return activity;
        }
    }
    return null;
};

/**
 * Locate an activity (and its section) by id anywhere in a plan tree.
 *
 * Exported for regen-block-reload.js, which rebuilds items from the same
 * plan tree on reload and for the approved-plan summary.
 *
 * @param {Array} plan
 * @param {string} activityId
 * @returns {Object|null} The activity object, or null.
 */
export const findActivity = (plan, activityId) => {
    for (const section of plan || []) {
        const activity = findActivityInSection(section, activityId);
        if (activity) {
            return activity;
        }
    }
    return null;
};

/**
 * @returns {boolean} Whether a live regen block is currently open (streaming).
 */
export const isRegenActive = () => activeList !== null;

/**
 * Start a live ACTIVITY-replan block: one spinner item per target activity,
 * head = icon + activity title (read from the current plan, since a replan keeps
 * the activity's id/title/type and only regenerates its detail).
 *
 * @param {Object} params
 * @param {string[]} params.targetIds - Activity UUIDs being regenerated.
 * @param {Array} params.plan - Current plan tree (for titles/types).
 * @returns {void}
 */
export const startRegenActivities = ({targetIds, plan}) => {
    const list = createBlock();
    if (!list) {
        return;
    }
    activeList = list;
    activeItems = new Map();
    activeDesc = new Map();
    sectionEntries = new Map();
    (targetIds || []).forEach((id) => {
        const activity = findActivity(plan, id);
        // A replan keeps the activity's description (only its detailed_plan is
        // regenerated). Capture it now so the live body matches the reload body
        // (the detailed_plan_activity event does NOT carry the description).
        activeDesc.set(id, (activity && activity.description) || '');
        const item = buildItem({
            id,
            title: (activity && activity.title) || 'Activity',
            iconType: (activity && activity.activity_type) || '',
            done: false,
        });
        list.appendChild(item);
        activeItems.set(id, item);
    });
};

/**
 * Fill a streaming activity item's detail and flip it to done, as each
 * ``detailed_plan_activity`` event arrives during an activity replan.
 *
 * @param {Object} data - { activity_id, title, description, data: <detailedPlan> }
 * @returns {void}
 */
export const regenOnActivityDetail = (data) => {
    if (!data || !activeItems.size) {
        return;
    }
    const item = activeItems.get(data.activity_id);
    if (!item) {
        return;
    }
    const bodyMd = formatActivityDetailMd({
        description: activeDesc.get(data.activity_id) || '',
        detailedPlan: data.data || null,
    });
    const detail = item.querySelector('.courseai-checklist-detail');
    if (detail) {
        detail.innerHTML = renderMarkdown(bodyMd);
    }
    item.classList.remove('is-loading');
    item.classList.add('is-done');
};

/**
 * Lazily create the regen block container the first time a section streams in.
 *
 * @returns {HTMLElement|null} The shared <ul>, or null when the feed is missing.
 */
const ensureSectionBlock = () => {
    if (!activeList) {
        activeList = createBlock();
        sectionEntries = new Map();
    }
    return activeList;
};

/**
 * Re-render a streaming section's Markdown detail (description + its activities,
 * each with whatever detailed plan has arrived so far). Called on every section,
 * activity, and detail event so the body grows in real time.
 *
 * @param {Object} entry - The section entry from {@link sectionEntries}.
 * @returns {void}
 */
const renderSectionEntry = (entry) => {
    const detail = entry.item.querySelector('.courseai-checklist-detail');
    if (!detail) {
        return;
    }
    const activityValues = entry.activities.values();
    const activities = [...activityValues]
        .sort((a, b) => (a.position || 0) - (b.position || 0))
        .map((a) => ({
            title: a.title,
            activity_type: a.activity_type,
            description: a.description || '',
            detailedPlan: a.detailedPlan || null,
        }));
    const sectionMd = formatSectionMd({
        name: '',
        description: entry.description || '',
        activities,
    });
    detail.innerHTML = renderMarkdown(sectionMd);
};

/**
 * Begin (or update) a streaming section item as its ``section`` event arrives
 * while adding or regenerating a section. Creates the bottom block lazily and one
 * spinner item per section — the top "structure I planned" checklist is untouched.
 *
 * @param {Object} data - { id, name, description } from the section event.
 * @returns {void}
 */
export const regenOnSectionStructure = (data) => {
    const list = ensureSectionBlock();
    if (!list) {
        return;
    }
    let entry = sectionEntries.get(data.id);
    if (!entry) {
        const item = buildItem({id: data.id, title: data.name || '', done: false});
        list.appendChild(item);
        entry = {item, description: data.description || '', activities: new Map()};
        sectionEntries.set(data.id, entry);
    } else {
        entry.description = data.description || entry.description;
        const nameEl = entry.item.querySelector('.courseai-checklist-name');
        if (nameEl && data.name) {
            nameEl.textContent = data.name;
        }
    }
    renderSectionEntry(entry);
};

/**
 * Attach a streaming activity (title/type/description) to its section's body as
 * its ``activity`` event arrives. No-op until the parent section streamed in.
 *
 * @param {Object} data - { section_id, id, title, activity_type, description, position }
 * @returns {void}
 */
export const regenOnSectionActivity = (data) => {
    const entry = sectionEntries.get(data.section_id);
    if (!entry) {
        return;
    }
    const existing = entry.activities.get(data.id) || {};
    let position = existing.position || 0;
    if (typeof data.position === 'number') {
        position = data.position;
    }
    entry.activities.set(data.id, {
        title: data.title || existing.title || '',
        activity_type: data.activity_type || existing.activity_type || '',
        description: data.description || existing.description || '',
        detailedPlan: existing.detailedPlan || null,
        position,
    });
    renderSectionEntry(entry);
};

/**
 * Fill a streaming activity's detailed plan as its ``detailed_plan_activity`` event
 * arrives, and flip the section item to done once every activity has its plan.
 *
 * @param {Object} data - { section_id, activity_id, data: <detailedPlan> }
 * @returns {void}
 */
export const regenOnSectionActivityDetail = (data) => {
    const entry = sectionEntries.get(data.section_id);
    if (!entry) {
        return;
    }
    const act = entry.activities.get(data.activity_id);
    if (act) {
        act.detailedPlan = data.data || act.detailedPlan || null;
    }
    renderSectionEntry(entry);
    const activityValues = entry.activities.values();
    const all = [...activityValues];
    if (all.length && all.every((a) => a.detailedPlan)) {
        entry.item.classList.remove('is-loading');
        entry.item.classList.add('is-done');
    }
};

/**
 * Finalize the live regen block: clamp every item's detail (the round settled).
 *
 * @returns {void}
 */
export const finalizeRegen = () => {
    if (!activeList) {
        return;
    }
    activeList.querySelectorAll('.courseai-checklist-detail').forEach((el) => clampDetail(el));
    activeList = null;
    activeItems = new Map();
    activeDesc = new Map();
    sectionEntries = new Map();
};
